//! Phase 4 (Issue 4) golden-fixture harness: GEV CP support clamping at small n.
//!
//! Loads `tests/golden/gev_smalln_golden.json` (generated by
//! `tools/generate_gev_smalln_golden.R` from the reference R package
//! `stephenjewson/fitdistcp`) and checks that the Rust [`predict_gev`] CP
//! quantiles are clamped to the GEV support, matching the reference
//! `fixgevrange` clamp.
//!
//! # What is compared
//!
//! - **CP quantiles** (`cp_quantiles`): the Rust `predict_gev` CP quantiles
//!   (DMGS expansion + `fixgevrange` clamp) vs. the reference `qgev_cp`'s
//!   `rh_flat_quantiles` after the reference `fixgevrange` clamp.
//! - **`ml_max`** and **`revert2ml`**: exact-match fields (§7.2).
//! - **The 1-in-100 return level** (`p = 0.99`): must be finite and within the
//!   support (`<= ml_max` for a negative shape), and must not be negative for a
//!   positive-support fit.
//!
//! # The defect (Issue 4)
//!
//! At small n the DMGS expansion can push a CP quantile outside the GEV support
//! (e.g. a negative 1-in-100 return level for a positive-support fit). The
//! reference `fixgevrange` (`005_utils.R`) clamps a value to the (nudged)
//! support bound. The Rust [`predict_gev`] now applies the same clamp and falls
//! back to the MLE quantile when a CP quantile still leaves the support.
//!
//! The `gev_smalln_clamp` fixture is the defect case: its raw DMGS CP quantile
//! at `p = 0.99` exceeds `ml_max`, so the clamp is genuinely exercised
//! (`cp_quantiles_raw[5] > ml_max` and `cp_quantiles[5] == ml_max`).
//!
//! # Tolerance policy (§7.2)
//!
//! The consolidated, canonical tolerance policy lives in
//! [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md); the summary
//! below is the subset relevant to this harness.
//!
//! The GEV CP quantiles use `rtol = 1e-3` (the Rust GEV keeps the numerical
//! third-derivative fallback, so the DMGS bias-correction term carries
//! finite-difference error; see §3.6). The optimizer-produced `ml_params` use
//! `rtol = 1e-4` (§3.2).

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::api::{predict_gev, PredictionRequest};
use fitdistcp_core::models::GenExtreme;

/// Tolerance for the GEV CP quantiles (numerical third derivatives, §3.6).
///
/// The `gev_smalln_clamp` fixture has a larger-magnitude shape (`~ -0.56`) than
/// the `gev_negshape` fixture (`~ -0.30`), so the numerical third-derivative
/// error in the DMGS bias-correction term is larger. The observed maximum
/// relative residual is `3.2e-3`; `5e-3` is a ~1.6× margin that still catches
/// any formula/sign bug. This is a documented relaxation of §3.6's `1e-3` for
/// this fixture (see [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md) §3.14).
const CPQ_RTOL: f64 = 5e-3;
const CPQ_ATOL: f64 = 1e-8;

/// Tolerance for the optimizer-produced `ml_params` (§3.2).
const OPT_RTOL: f64 = 1e-4;
const OPT_ATOL: f64 = 1e-6;

/// The reference `fdalpha` default for the quantile-derived density.
const FDALPHA: f64 = 0.01;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_bool(&self) -> bool {
        match self {
            Json::Bool(b) => *b,
            other => panic!("expected bool, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        b'b' => s.push('\u{0008}'),
                        b'f' => s.push('\u{000C}'),
                        b'u' => {
                            let hex = std::str::from_utf8(&self.bytes[self.pos + 1..self.pos + 5])
                                .expect("utf8 hex");
                            let code = u32::from_str_radix(hex, 16).expect("hex");
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            self.pos += 4;
                        }
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "gev_smalln_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

fn compare_vec(actual: &[f64], expected: &[f64], rtol: f64, atol: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: length mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_close(*a, *e, rtol, atol, &format!("{what}[{i}]"));
    }
}

/// Run `predict_gev` on a fixture dataset and return the [`FitResult`].
fn run_predict_gev(y: &[f64], p_grid: &[f64]) -> fitdistcp_core::api::FitResult {
    let req = PredictionRequest {
        y: y.to_vec(),
        x: vec![1.0, 1.3, 1.6, 1.9, 2.2],
        p: p_grid.to_vec(),
        t: None,
        t0: None,
        n0: None,
        means: None,
    };
    // The reference `gev_setics` seeds the optimizer; the Rust `fit` uses the
    // same heuristic internally, so a generic init is fine here.
    predict_gev(GenExtreme, &req, &[1.4, 0.3, -0.1], FDALPHA)
}

/// The 1-in-100 return level is the last `p` in the grid (`p = 0.99`).
const P_1IN100_IDX: usize = 5;

#[test]
fn golden_gev_smalln_cp_quantiles_clamped_to_support() {
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();
    assert_eq!(p_grid.len(), 6, "p_grid must include the 1-in-100 level");
    assert_close(p_grid[P_1IN100_IDX], 0.99, 1e-12, 1e-12, "p_grid[5]");

    // (model name, dataset key) pairs.
    for (name, ds_key) in [
        ("gev_smalln", "y_smalln"),
        ("gev_smalln_clamp", "y_smalln_clamp"),
    ] {
        let y = datasets.get(ds_key).as_f64_vec();
        assert_eq!(y.len(), 20, "{name}: fixture must have n = 20");
        let m = models.get(name);

        let r = run_predict_gev(&y, &p_grid);

        // The fitted shape must be negative (finite upper support bound).
        assert!(
            r.ml_params[2] < 0.0,
            "{name}: expected negative shape, got {}",
            r.ml_params[2]
        );

        // The Rust MLE should match the reference MLE (optimizer tolerance).
        let ref_params = m.get("params").as_f64_vec();
        assert_close(r.ml_params[0], ref_params[0], OPT_RTOL, OPT_ATOL, "loc");
        assert_close(r.ml_params[1], ref_params[1], OPT_RTOL, OPT_ATOL, "scale");
        assert_close(r.ml_params[2], ref_params[2], OPT_RTOL, OPT_ATOL, "shape");

        // revert2ml is an exact-match field (§7.2).
        let ref_revert = m.get("revert2ml").as_bool();
        assert_eq!(
            GenExtreme.revert2ml(r.ml_params[2]),
            ref_revert,
            "{name}: revert2ml mismatch"
        );
        assert!(!ref_revert, "{name}: fixture should be in the DMGS regime");

        // ml_max is an exact-match field: loc - scale/shape for negative shape.
        let ref_ml_max = m.get("ml_max").as_f64();
        let ml_max = GenExtreme.ml_max(r.ml_params[0], r.ml_params[1], r.ml_params[2]);
        assert_close(ml_max, ref_ml_max, 1e-6, 1e-8, "ml_max");

        // CP quantiles (DMGS + fixgevrange clamp) vs. the reference clamp.
        compare_vec(
            &r.cp_quantiles,
            &m.get("cp_quantiles").as_f64_vec(),
            CPQ_RTOL,
            CPQ_ATOL,
            &format!("{name}.cp_quantiles"),
        );

        // Every CP quantile must be finite and within the support.
        for (i, &q) in r.cp_quantiles.iter().enumerate() {
            assert!(q.is_finite(), "{name}: cp_quantiles[{i}] = {q} not finite");
            assert!(
                q <= ml_max + 1e-9,
                "{name}: cp_quantiles[{i}] = {q} exceeds ml_max = {ml_max}"
            );
        }

        // The 1-in-100 return level must be finite, within support, and
        // non-negative (a positive-support fit must not yield a negative
        // return level — the Issue 4 defect).
        let q100 = r.cp_quantiles[P_1IN100_IDX];
        assert!(
            q100.is_finite(),
            "{name}: 1-in-100 CP quantile = {q100} not finite"
        );
        assert!(
            q100 >= 0.0,
            "{name}: 1-in-100 CP quantile = {q100} is negative"
        );
        assert!(
            q100 <= ml_max + 1e-9,
            "{name}: 1-in-100 CP quantile = {q100} exceeds ml_max = {ml_max}"
        );
    }
}

#[test]
fn golden_gev_smalln_clamp_is_exercised() {
    // The `gev_smalln_clamp` fixture is the defect case: its raw DMGS CP
    // quantile at p = 0.99 exceeds `ml_max`, so the clamp changes the value.
    let root = load_fixture();
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();

    let y = datasets.get("y_smalln_clamp").as_f64_vec();
    let m = models.get("gev_smalln_clamp");

    let raw = m.get("cp_quantiles_raw").as_f64_vec();
    let clamped = m.get("cp_quantiles").as_f64_vec();
    let ml_max = m.get("ml_max").as_f64();

    // The raw 1-in-100 CP quantile leaves the support...
    assert!(
        raw[P_1IN100_IDX] > ml_max,
        "fixture must have a raw CP quantile outside the support: raw = {}, ml_max = {ml_max}",
        raw[P_1IN100_IDX]
    );
    // ...and the reference clamp pins it to the bound (the reference `ml_max`).
    assert_close(
        clamped[P_1IN100_IDX],
        ml_max,
        1e-6,
        1e-8,
        "clamped 1-in-100 == ml_max",
    );

    // The Rust `predict_gev` must reproduce the clamped value (not the raw one).
    let r = run_predict_gev(&y, &p_grid);
    assert_close(
        r.cp_quantiles[P_1IN100_IDX],
        clamped[P_1IN100_IDX],
        CPQ_RTOL,
        CPQ_ATOL,
        "rust clamped 1-in-100",
    );
    // The Rust clamp must pin the value to the Rust `fixgevrange` bound
    // `loc - scale/(shape - minxi)` (self-consistent: the Rust-fitted params
    // differ from the reference's by the optimizer tolerance, so the bound
    // differs by ~1e-7).
    let minxi = 1e-7_f64;
    let rust_bound = r.ml_params[0] - r.ml_params[1] / (r.ml_params[2] - minxi);
    assert_close(
        r.cp_quantiles[P_1IN100_IDX],
        rust_bound,
        1e-9,
        1e-9,
        "rust clamped 1-in-100 == rust fixgevrange bound",
    );
    let rust_ml_max = GenExtreme.ml_max(r.ml_params[0], r.ml_params[1], r.ml_params[2]);
    assert!(
        r.cp_quantiles[P_1IN100_IDX] <= rust_ml_max + 1e-9,
        "rust 1-in-100 CP quantile = {} exceeds ml_max = {rust_ml_max}",
        r.cp_quantiles[P_1IN100_IDX]
    );
}
